import {
    ArrayShape,
    CallExpressionShape,
    IdentifierShape,
    path,
    TaggedTemplateExpressionShape,
    TemplateExpressionShape,
    TemplateSpanShape,
    ts,
    VariableStatementShape,
} from '@servicenow/sdk-build-core'
import { NowIncludeShape } from '@servicenow/sdk-build-plugins'
import { createTestContext } from '../test-utils'

describe('Basic syntax plugins', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })

    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())

    describe('VariableStatementShape', () => {
        test(`can transform into a VariableStatement node via commit`, async () => {
            const project = ctx.createProject()
            const file = project.addFile({ path: 'test.now.ts', content: '// code' })

            const { changedFiles } = await project.transform(
                new VariableStatementShape({
                    source: file.addStatement(),
                    isExported: true,
                    variableName: 'code',
                    initializer: new NowIncludeShape({
                        source: file.unwrap(),
                        path: './script.js',
                        includedText: '',
                    }),
                })
            )

            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe("// code\nexport const code = Now.include('./script.js')\n")
        })

        test(`can transform CallExpression into a VariableStatement node via commit`, async () => {
            const project = ctx.createProject()
            project.addFile({
                path: 'lib.d.ts',
                content: `
                    declare module '@servicenow/sdk/core' {
                        export function myFunc(...args: any[]): any
                    }
                    `,
            })
            const file = project.addFile({
                path: 'test.now.ts',
                content: `import { myFunc } from "@servicenow/sdk/core"`,
            })
            const stmt = file.addStatement(`myFunc(123, true)`)
            if (!stmt.isKind(ts.SyntaxKind.ExpressionStatement)) {
                fail(`Statement is not an expression statement: ${stmt.getFullText()}`)
            }
            const target = stmt.getExpression()
            const { changedFiles } = await project.transform([
                new VariableStatementShape({
                    source: target,
                    variableName: 'message',
                    isExported: true,
                    initializer: new CallExpressionShape({
                        source: target,
                        callee: 'myFunc',
                        args: [123, true],
                    }),
                }),
            ])
            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe(
                "import { myFunc } from '@servicenow/sdk/core'\nexport const message = myFunc(123, true)\n"
            )
        })

        test(`can transform CallExpression within VariableStatement into a VariableStatement node via commit`, async () => {
            const project = ctx.createProject()
            project.addFile({
                path: 'lib.d.ts',
                content: `
                    declare module '@servicenow/sdk/core' {
                        export function myFunc(...args: any[]): any
                    }
                    `,
            })
            const file = project.addFile({
                path: 'test.now.ts',
                content: `import { myFunc } from "@servicenow/sdk/core"`,
            })
            const stmt = file.addStatement(`export const message = myFunc(123, true)`)
            if (!stmt.isKind(ts.SyntaxKind.VariableStatement)) {
                fail(`Statement is not an expression statement: ${stmt.getFullText()}`)
            }
            const target = stmt.getDeclarationList().getDeclarations()[0].getInitializer()
            const { changedFiles } = await project.transform([
                new VariableStatementShape({
                    source: target,
                    variableName: 'newMessage',
                    isExported: true,
                    initializer: new CallExpressionShape({
                        source: target,
                        callee: 'myFunc',
                        args: [123, true],
                    }),
                }),
            ])
            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe(
                "import { myFunc } from '@servicenow/sdk/core'\nexport const newMessage = myFunc(123, true)\n"
            )
        })
    })

    describe('CallExpressionShape', () => {
        test('can transform into a CallExpression node via commit', async () => {
            const project = ctx.createProject()
            const file = project.addFile({ path: 'test.now.ts', content: '' })

            const { changedFiles } = await project.transform([
                new VariableStatementShape({
                    source: file.addStatement(),
                    variableName: 'message',
                    initializer: 'hello',
                }),
                new CallExpressionShape({
                    source: file.addStatement(),
                    callee: 'myFunc',
                    args: [new IdentifierShape({ source: file.unwrap(), name: 'message' }), 123, true],
                }),
            ])

            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe(`const message = 'hello'
myFunc(message, 123, true)
`)
        })

        test('can transform into a CallExpression node via commit with existing code', async () => {
            const project = ctx.createProject()
            project.addFile({
                path: 'lib.d.ts',
                content: `
                    declare module '@servicenow/sdk/core' {
                        export function myFunc(...args: any[]): any
                    }
                    `,
            })
            const file = project.addFile({
                path: 'test.now.ts',
                content: 'import { myFunc } from "@servicenow/sdk/core"',
            })

            const { changedFiles } = await project.transform([
                new VariableStatementShape({
                    source: file.addStatement(`const message = 'hello'`),
                    variableName: 'greeting',
                    initializer: 'hello',
                }),
                new CallExpressionShape({
                    source: file.addStatement(`myFunc(message, 123, true)`),
                    callee: 'myFunc',
                    args: [new IdentifierShape({ source: file.unwrap(), name: 'greeting' }), 123, true],
                }),
            ])

            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe(`import { myFunc } from '@servicenow/sdk/core'
const greeting = 'hello'
myFunc(greeting, 123, true)
`)
        })
    })

    describe('ArrayShape', () => {
        test('can transform into an ArrayLiteralExpression node via commit', async () => {
            const project = ctx.createProject()
            const file = project.addFile({ path: 'test.now.ts', content: '' })

            const { changedFiles } = await project.transform([
                new VariableStatementShape({
                    source: file.addStatement(),
                    variableName: 'item',
                    initializer: 'a',
                }),
                new VariableStatementShape({
                    source: file.addStatement(),
                    variableName: 'myArray',
                    initializer: new ArrayShape({
                        source: file.unwrap(),
                        elements: [new IdentifierShape({ source: file.unwrap(), name: 'item' }), 1, false, { b: 2 }],
                    }),
                }),
            ])

            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe(`const item = 'a'
const myArray = [
    item,
    1,
    false,
    {
        b: 2,
    },
]
`)
        })
        test('can transform into an ArrayLiteralExpression node via commit with existing code', async () => {
            const project = ctx.createProject()
            const file = project.addFile({ path: 'test.now.ts', content: '' })

            const { changedFiles } = await project.transform([
                new VariableStatementShape({
                    source: file.addStatement(`const item = 'a'`),
                    variableName: 'item',
                    initializer: 'a',
                }),
                new VariableStatementShape({
                    source: file.addStatement(`const myArray = []`),
                    variableName: 'myArray',
                    initializer: new ArrayShape({
                        source: file.unwrap(),
                        elements: [new IdentifierShape({ source: file.unwrap(), name: 'item' }), 1, false, { b: 2 }],
                    }),
                }),
            ])

            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe(`const item = 'a'
const myArray = [
    item,
    1,
    false,
    {
        b: 2,
    },
]
`)
        })
    })

    describe('TemplateExpressionShape', () => {
        test(`transforms into a TemplateExpression node with a simple string span`, async () => {
            const project = ctx.createProject()
            const file = project.addFile({ path: 'test.now.ts', content: '' })

            const { changedFiles } = await project.transform([
                new VariableStatementShape({
                    source: file.addStatement(),
                    variableName: 'name',
                    initializer: 'Bob',
                }),
                new VariableStatementShape({
                    source: file.addStatement(),
                    isExported: true,
                    variableName: 'greeting',
                    initializer: new TemplateExpressionShape({
                        source: file.unwrap(),
                        literalText: 'Hello, ',
                        spans: [
                            new TemplateSpanShape({
                                source: file.unwrap(),
                                literalText: '!',
                                expression: new IdentifierShape({
                                    source: file.unwrap(),
                                    name: 'name',
                                }),
                            }),
                        ],
                    }),
                }),
            ])

            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe("const name = 'Bob'\nexport const greeting = `Hello, ${name}!`\n")
        })

        test(`transforms into a TemplateExpression node with a complex object span`, async () => {
            const project = ctx.createProject()
            const file = project.addFile({ path: 'test.now.ts', content: '' })

            const { changedFiles } = await project.transform([
                new VariableStatementShape({
                    source: file.addStatement(),
                    variableName: 'user',
                    initializer: { name: 'Bob' },
                }),
                new VariableStatementShape({
                    source: file.addStatement(),
                    isExported: true,
                    variableName: 'greeting',
                    initializer: new TemplateExpressionShape({
                        source: file.unwrap(),
                        literalText: 'Hello, ',
                        spans: [
                            new TemplateSpanShape({
                                source: file.unwrap(),
                                literalText: '!',
                                expression: new IdentifierShape({
                                    source: file.unwrap(),
                                    name: 'user.name',
                                }),
                            }),
                        ],
                    }),
                }),
            ])

            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe(`const user = {
    name: 'Bob',
}
export const greeting = \`Hello, \${user.name}!\`
`)
        })

        test(`can transform into a TaggedTemplateExpression node`, async () => {
            const project = ctx.createProject()
            const file = project.addFile({ path: 'index.now.ts', content: '' })

            const { changedFiles } = await project.transform(
                new TaggedTemplateExpressionShape({
                    source: file.addStatement(),
                    tag: 'script',
                    template: new TemplateExpressionShape({
                        source: file.unwrap(),
                        literalText: '// code',
                    }),
                })
            )

            expect(changedFiles).toHaveLength(1)
            expect(file).toStrictEqual(changedFiles[0])
            expect(file.getContent()).toBe('script`// code`\n')
        })

        test(`can toShape a TemplateExpression`, async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'index.now.ts',
                content: `
const firstname = 'Bob'
const lastname = 'Barker'
const message = \`Hello, \${firstname} \${lastname}. How are you?\`
`,
            })

            const templateExpression = (await file.getShapes()).find((s) => s.is(TemplateExpressionShape))
            expect(templateExpression).toBeDefined()
            expect(templateExpression.getValue()).toBe('Hello, Bob Barker. How are you?')
            expect(templateExpression.getCode()).toBe('`Hello, ${firstname} ${lastname}. How are you?`')
        })

        test('can render different values than it originally had', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'index.now.ts',
                content: `
const greeting = 'Hello'
const name = 'Bob'
const message = \`\${greeting}, \${name}!\`
`,
            })

            const templateExpression = (await file.getShapes()).find((s) => s.is(TemplateExpressionShape))
            expect(templateExpression.getValue()).toBe('Hello, Bob!')
            expect(templateExpression.getValue({ 0: 'Howdy' })).toBe('Howdy, Bob!')
            expect(templateExpression.getValue({ 1: 'Sam' })).toBe('Hello, Sam!')
            expect(templateExpression.getValue((e) => e.toString().getValue().toUpperCase())).toBe('HELLO, BOB!')
            expect(
                templateExpression.getValue({
                    0: (e) => `_${e.getValue()}_`,
                    1: (e) => `__${e.getValue()}__`,
                })
            ).toBe('_Hello_, __Bob__!')
        })
    })
})
